<script setup lang="ts">import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {api} from '../../shared/api/client';const step=ref(1);const form=reactive({scene:'STUDY',dailyMinutes:30,weeklyFrequency:3,preferredDifficulty:2});const router=useRouter();async function finish(){await api.patch('/me/preferences',{dailyMinutes:form.dailyMinutes,weeklyFrequency:form.weeklyFrequency,preferredDifficulty:form.preferredDifficulty});router.push('/goals')}</script>
<template><main class="page onboarding"><div class="page-head"><div><p class="eyebrow">开始设置</p><h1>你的节奏</h1></div><span>第 {{step}} / 2 步</span></div><div class="progress"><span :style="{width:`${step*50}%`}"></span></div><section v-if="step===1" class="band stack"><h2>现在最想关注什么？</h2><div class="scene-grid"><button v-for="item in [{v:'STUDY',l:'学习'},{v:'FITNESS',l:'身体照顾'},{v:'CAREER',l:'职场'},{v:'EMOTIONAL_SUPPORT',l:'情绪支持'}]" :key="item.v" class="secondary" :aria-pressed="form.scene===item.v" @click="form.scene=item.v">{{item.l}}</button></div><div class="actions"><button class="primary" @click="step=2">下一步</button></div></section><section v-else class="band stack"><h2>一周安排</h2><div class="field"><label for="minutes">每天投入（分钟）</label><input id="minutes" v-model.number="form.dailyMinutes" type="number" min="5" max="720"></div><div class="field"><label for="frequency">每周频次</label><input id="frequency" v-model.number="form.weeklyFrequency" type="number" min="1" max="7"></div><div class="actions"><button class="secondary" @click="step=1">返回</button><button class="primary" @click="finish">保存并创建目标</button></div></section></main></template>
<style scoped>.onboarding{max-width:780px}.onboarding>.progress{height:10px;margin-bottom:18px;box-shadow:inset 0 1px 2px rgb(0 0 0 / 6%)}.onboarding .band{padding:22px;border:1px solid var(--border);border-radius:calc(var(--radius) + 4px);background:color-mix(in srgb,var(--surface) 90%,transparent);box-shadow:var(--shadow-soft)}.page-head>span{align-self:center;padding:5px 9px;border:1px solid var(--border);border-radius:999px;background:var(--surface);color:var(--muted);font-size:12px;font-weight:800}.scene-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.scene-grid button{position:relative;min-height:92px;overflow:hidden;align-items:end;justify-content:start;text-align:left;background:var(--surface);font-size:15px}.scene-grid button::before{content:"";position:absolute;inset:10px auto auto 12px;width:30px;height:30px;border-radius:11px;background:linear-gradient(135deg,var(--primary),var(--accent));opacity:.16}.scene-grid button[aria-pressed=true]{border-color:var(--primary);background:color-mix(in srgb,var(--primary-soft) 64%,var(--surface));color:var(--primary);font-weight:800;box-shadow:var(--shadow-soft)}.scene-grid button[aria-pressed=true]::after{content:"";position:absolute;inset:auto 12px 9px;height:3px;background:linear-gradient(90deg,var(--primary),var(--accent));border-radius:999px}@media(prefers-reduced-motion:no-preference){.scene-grid button{animation:scene-enter var(--motion-medium) ease-out both}.scene-grid button:hover{transform:translateY(-2px)}.scene-grid button:nth-child(2){animation-delay:45ms}.scene-grid button:nth-child(3){animation-delay:90ms}.scene-grid button:nth-child(4){animation-delay:135ms}.scene-grid button[aria-pressed=true]::after{animation:scene-line var(--motion-medium) ease-out both}}@keyframes scene-enter{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}@keyframes scene-line{from{transform:scaleX(.2);transform-origin:left}to{transform:scaleX(1);transform-origin:left}}@media(max-width:520px){.scene-grid{grid-template-columns:1fr}}</style>
